mapper.select:
SELECT q.id,v.title,v.question_type AS type,v.difficulty,q.status,q.revision,q.favorite,
  v.id AS version_id,v.version_number,v.standard_status,q.updated_at
FROM question q JOIN question_version v
  ON v.owner_id=q.owner_id AND v.question_id=q.id AND v.id=q.current_version_id
WHERE q.owner_id=#{owner} AND q.status=#{status}
AND v.title LIKE #{pattern} ESCAPE '!'
AND v.question_type=#{type}
AND v.difficulty=#{difficulty}
AND v.scenario LIKE #{scenePattern} ESCAPE '!'
AND q.favorite=#{favorite}

  AND EXISTS (SELECT 1 FROM question_version_dimension d WHERE d.owner_id=q.owner_id
    AND d.question_id=q.id AND d.version_id=v.id AND d.dimension=#{dimension})


  AND EXISTS (SELECT 1 FROM question_version_topic t WHERE t.owner_id=q.owner_id
    AND t.question_id=q.id AND t.version_id=v.id AND t.topic_id=#{topicId})


  AND EXISTS (SELECT 1 FROM question_knowledge_reference r WHERE r.owner_id=q.owner_id
    AND r.question_id=q.id AND r.version_id=v.id AND r.knowledge_item_id=#{knowledgeId})

AND q.id > #{cursor}
ORDER BY q.id LIMIT #{limit}

SELECT id,version_number AS number,title,created_at FROM question_version
WHERE owner_id=#{owner} AND question_id=#{id}
AND version_number < #{before}
ORDER BY version_number DESC LIMIT #{limit}

SELECT id,question_id,version_id,exposure_kind AS kind,created_at FROM question_exposure
WHERE owner_id=#{owner} AND question_id=#{id}

  AND (created_at < #{beforeTime} OR (created_at=#{beforeTime} AND id < #{beforeId}))

ORDER BY created_at DESC,id DESC LIMIT #{limit}
